const item = $input.item.json;

const readings = item.sensorReadings || [];
const tempRangeMin = parseFloat(item.tempRangeMin) ?? 2;
const tempRangeMax = parseFloat(item.tempRangeMax) ?? 8;
const productType = item.productType || 'Unspecified';
const batchId = item.batchId || item.shipmentId || 'UNKNOWN';
const transferHubsCount = parseInt(item.transferHubsCount, 10) || 0;
const shipmentDurationHours = parseFloat(item.shipmentDurationHours) || (readings.length > 1
  ? (new Date(readings[readings.length - 1].timestamp) - new Date(readings[0].timestamp)) / 3600000
  : 0);

// Sort readings chronologically
const sorted = [...readings].sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));

// Excursion detection: minutes spent outside the validated temperature range
let excursionMinutes = 0;
let maxDeviationC = 0;
for (let i = 0; i < sorted.length; i++) {
  const t = parseFloat(sorted[i].temperatureC);
  if (isNaN(t)) continue;
  const belowBy = tempRangeMin - t;
  const aboveBy = t - tempRangeMax;
  if (belowBy > 0 || aboveBy > 0) {
    const intervalMinutes = i < sorted.length - 1
      ? (new Date(sorted[i + 1].timestamp) - new Date(sorted[i].timestamp)) / 60000
      : 5; // assume 5 min for the last reading if no next point exists
    excursionMinutes += Math.max(intervalMinutes, 0);
    maxDeviationC = Math.max(maxDeviationC, belowBy, aboveBy);
  }
}

// Mean Kinetic Temperature (MKT) - Haynes equation, the standard cold-chain QA metric.
// Ea = activation energy (kJ/mol), R = gas constant (kJ/mol*K). 83.144 kJ/mol is the commonly used default.
const Ea = 83.144;
const R = 0.0083144;
const kelvinReadings = sorted
  .map(r => parseFloat(r.temperatureC))
  .filter(t => !isNaN(t))
  .map(t => t + 273.15);

let meanKineticTempC = null;
if (kelvinReadings.length > 0) {
  const sumExp = kelvinReadings.reduce((sum, tk) => sum + Math.exp(-Ea / (R * tk)), 0);
  const mktK = -Ea / (R * Math.log(sumExp / kelvinReadings.length));
  meanKineticTempC = Math.round((mktK - 273.15) * 100) / 100;
}

const routeRiskFactor = Math.round(
  ((transferHubsCount * 0.15) + (shipmentDurationHours / 24) * 0.05) * 100
) / 100;

return {
  json: {
    batchId,
    productType,
    tempRangeMin,
    tempRangeMax,
    readingCount: sorted.length,
    excursionMinutes: Math.round(excursionMinutes),
    maxDeviationC: Math.round(maxDeviationC * 100) / 100,
    meanKineticTempC,
    transferHubsCount,
    shipmentDurationHours: Math.round(shipmentDurationHours * 10) / 10,
    routeRiskFactor,
    shipmentId: item.shipmentId,
    productShelfLifeSensitiveQ10: item.productQ10 ?? 2.5 // default Q10 coefficient if ERP doesn't supply one
  }
};

const item = $input.item.json;
const {
  excursionMinutes, meanKineticTempC,
  tempRangeMax, routeRiskFactor, productShelfLifeSensitiveQ10,
  shipmentDurationHours
} = item;

const ITERATIONS = 1000;
const SPOILAGE_THRESHOLD_PCT_POTENCY = 90; // below this remaining potency, the batch is considered compromised

function randomNormal(mean, stdDev) {
  let u = 0, v = 0;
  while (u === 0) u = Math.random();
  while (v === 0) v = Math.random();
  const z = Math.sqrt(-2.0 * Math.log(u)) * Math.cos(2.0 * Math.PI * v);
  return mean + z * stdDev;
}

// Baseline degradation model: Q10 reaction kinetics. Every 10C the Mean Kinetic Temperature sits
// above the top of the validated range roughly multiplies the degradation rate by the product's Q10.
const baseDegradationPerHourAtMax = 0.02; // assumed baseline % potency loss/hr at the top of validated range
const referenceMKT = meanKineticTempC ?? tempRangeMax;
const degreesAboveMax = Math.max(referenceMKT - tempRangeMax, 0);

const endingPotencies = [];
let compromisedCount = 0;

for (let i = 0; i < ITERATIONS; i++) {
  // Sample uncertainty in sensor accuracy and product-specific sensitivity per run
  const sensorNoiseC = randomNormal(0, 0.5);
  const q10Sample = Math.max(randomNormal(productShelfLifeSensitiveQ10, 0.3), 1.1);
  const excursionSeverityC = Math.max(degreesAboveMax + sensorNoiseC, 0);

  const rateMultiplier = Math.pow(q10Sample, excursionSeverityC / 10);
  const effectiveHoursAtRisk = (excursionMinutes / 60) || (shipmentDurationHours * 0.05);

  const routeStress = 1 + (routeRiskFactor || 0);
  const potencyLoss = baseDegradationPerHourAtMax * rateMultiplier * effectiveHoursAtRisk * routeStress
    * (1 + randomNormal(0, 0.1)); // run-to-run model noise

  const endingPotency = Math.max(100 - potencyLoss, 0);
  endingPotencies.push(Math.round(endingPotency * 100) / 100);
  if (endingPotency < SPOILAGE_THRESHOLD_PCT_POTENCY) compromisedCount++;
}

endingPotencies.sort((a, b) => a - b);
const percentile = (p) => endingPotencies[Math.floor((p / 100) * (endingPotencies.length - 1))];

const simulation = {
  iterations: ITERATIONS,
  spoilageThresholdPctPotency: SPOILAGE_THRESHOLD_PCT_POTENCY,
  p10EndingPotencyPct: percentile(10),
  p50EndingPotencyPct: percentile(50),
  p90EndingPotencyPct: percentile(90),
  spoilageProbabilityPct: Math.round((compromisedCount / ITERATIONS) * 1000) / 10
};

return { json: { ...item, simulation } };

const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  const pct = item.simulation.spoilageProbabilityPct;
  const risk = pct >= 25 ? 'Recall' : pct >= 10 ? 'Quarantine' : pct >= 3 ? 'Monitor' : 'Safe';
  parsed = {
    riskLevel: risk,
    narrativeSummary: `Batch ${item.batchId} (${item.productType}) spent ${item.excursionMinutes} minutes outside its validated ${item.tempRangeMin}-${item.tempRangeMax}C range. The predictive model puts a ${pct}% chance this batch falls below the potency threshold, with a median projected ending potency of ${item.simulation.p50EndingPotencyPct}%.`,
    recommendedActions: [
      'Hold the batch pending lab confirmation before it reaches shelves.',
      'Pull the full sensor log for this shipment and review the excursion window.',
      'Flag the route/carrier for review if excursions recur on this lane.'
    ]
  };
}

const reportGeneratedAt = new Date().toISOString();
const actionsText = (parsed.recommendedActions || [])
  .map((a, i) => `${i + 1}. ${a}`)
  .join('\n');

const reportBody = `Cold-Chain Predictive Recall Report\nGenerated: ${reportGeneratedAt}\n\nBatch: ${item.batchId} (${item.productType})\nShipment: ${item.shipmentId}\nValidated Range: ${item.tempRangeMin}C to ${item.tempRangeMax}C\n\nExcursion Time: ${item.excursionMinutes} minutes | Max Deviation: ${item.maxDeviationC}C\nMean Kinetic Temperature: ${item.meanKineticTempC}C\nTransfer Hubs: ${item.transferHubsCount} | Duration: ${item.shipmentDurationHours} hours\n\nSimulated Outcomes (${item.simulation.iterations} runs):\n- Pessimistic (P10) Ending Potency: ${item.simulation.p10EndingPotencyPct}%\n- Median (P50) Ending Potency: ${item.simulation.p50EndingPotencyPct}%\n- Optimistic (P90) Ending Potency: ${item.simulation.p90EndingPotencyPct}%\n- Probability Below Threshold: ${item.simulation.spoilageProbabilityPct}%\n\nRisk Level: ${parsed.riskLevel}\n\n${parsed.narrativeSummary}\n\nRecommended Actions:\n${actionsText}`;

return {
  json: {
    ...item,
    ...parsed,
    reportGeneratedAt,
    reportBody
  }
};
